```json
{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) c, avg(duration)/1e6 avg_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name IN ('TripRepository.findAll','SELECT travel2.entity.Trip') GROUP BY 1",
          "claim": "Travel2 DB spans take about 30 s and all error in the incident window, versus about 1 ms normally."
        },
        {
          "kind": "log",
          "sql": "SELECT level, substr(message,1,120) m, count(*) c FROM abnormal_logs WHERE service_name='ts-travel2-service' AND level IN ('ERROR','SEVERE','WARN') GROUP BY 1,2 ORDER BY c DESC",
          "claim": "Travel2 logs Hikari pool timeouts after 30000ms, JDBC communication link failures and SQLState 08S01 errors."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) c, avg(duration)/1e6 avg_ms FROM normal_traces WHERE service_name='ts-travel2-service' AND span_name IN ('TripRepository.findAll','SELECT travel2.entity.Trip') GROUP BY 1,2",
          "claim": "Normal period: travel2 DB spans average under 1 ms with no errors."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name callee, s.span_name, count(*) n, avg(s.duration)/1e6 avg_ms, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name='ts-route-plan-service' AND s.service_name='ts-travel2-service' GROUP BY 1,2",
          "claim": "Route-plan calls to travel2 trips/left take about 30 s and return errors."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) c, avg(duration)/1e6 avg_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name IN ('ts-route-plan-service','ts-travel-plan-service') AND attr_status_code='Error' AND span_name LIKE 'POST%' GROUP BY 1,2",
          "claim": "Route-plan and travel-plan POST spans error at about 30 s, consistent with the downstream timeout chain."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name callee, s.span_name, count(*) n, avg(s.duration)/1e6 avg_ms, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel-plan-service' GROUP BY 1,2",
          "claim": "Ui-dashboard calls to travel-plan quickest take about 30 s and error out."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) c, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%travel2service%' GROUP BY 1,2",
          "claim": "Ui-dashboard's direct POST to travel2 trips/left averages about 17.7 s in the incident window."
        }
      ]
    }
  ]
}
